public const string WhileConditionKernel_Source = @"extern ""C"" __global__ void InlineOutVarKernels_WhileConditionKernel(GSharpArray<int> input, GSharpArray<int> output){
int tid = threadIdx.x;
int curr = input[tid];
int sum = 0;
int nextVal;
while(TryStep(curr,&nextVal))
{
sum+=nextVal;
curr=nextVal;
}
output[tid]=sum;
}
";
